// Извлекаем входные данные от Gateway
const input = $json;
return {
  user_id: input.user_id,
  chat_id: input.chat_id,
  text: input.text,
  first_name: input.first_name,
  username: input.username,
  is_callback: input.is_callback,
  callback_data: input.callback_data,
  timestamp: input.timestamp,
  message_id: input.message_id
};

// ============================================================
// SESSION MANAGER: Merge Context (v3.0)
// ============================================================

const trigger = $('Extract Input').first().json;
const sessionResult = $('Upsert Session').all();
const session = sessionResult.length > 0 && sessionResult[0].json.session_id 
  ? sessionResult[0].json 
  : { session_id: null, language: 'ru', status: 'new' };

const vacanciesResult = $('Load Vacancies').all();
const vacancies = vacanciesResult.map(v => v.json).filter(v => v.id);

const historyResult = $('Load Chat History').all();
const chatHistory = historyResult.map(h => h.json).filter(h => h.user_message);

// Собираем известные данные из истории
let knownData = {
  first_name: null,
  last_name: null,
  citizenship: null,
  age: null,
  experience: null,
  documents_status: null,
  phone: null,
  position_interest: null
};

// Объединяем extracted_data из всей истории (от старых к новым)
chatHistory.slice().reverse().forEach(h => {
  if (h.extracted_data) {
    try {
      const data = typeof h.extracted_data === 'string' 
        ? JSON.parse(h.extracted_data) 
        : h.extracted_data;
      Object.keys(data).forEach(key => {
        if (data[key] && data[key] !== 'unknown' && data[key] !== null && data[key] !== '') {
          knownData[key] = data[key];
        }
      });
    } catch (e) {
      // ignore parse errors
    }
  }
});

// Определяем, новый ли это пользователь
const isNewUser = chatHistory.length === 0;

// Форматируем вакансии для промпта
const vacanciesText = vacancies.length > 0
  ? vacancies.map(v => 
      `📌 ${v.position_name}\n💰 Зарплата: ${v.salary_min || '?'}-${v.salary_max || '?'} руб.\n📋 ${v.benefits || 'Условия уточняйте'}`
    ).join('\n\n')
  : 'Вакансии загружаются...';

// Форматируем историю для контекста AI
const chatHistoryText = chatHistory.length > 0
  ? 'ПОСЛЕДНИЕ СООБЩЕНИЯ (от новых к старым):\n' + chatHistory.slice(0, 10).map((h, i) => 
      `${i + 1}. Кандидат: "${h.user_message}"\n   Бот: "${(h.bot_response || '').substring(0, 100)}${h.bot_response?.length > 100 ? '...' : ''}"`
    ).join('\n\n')
  : 'История диалога пуста (новый пользователь)';

// Финальный контекст
return {
  // User data
  user_id: trigger.user_id,
  user_message: trigger.text,
  chat_id: trigger.chat_id,
  first_name: trigger.first_name || knownData.first_name || '',
  username: trigger.username,
  message_id: trigger.message_id,

  // Session data
  session_id: session.session_id,
  language: session.language || 'ru',
  session_status: session.status || 'new',
  is_new_user: isNewUser,

  // Vacancy data
  vacancies: vacancies,
  vacancies_text: vacanciesText,

  // Known candidate data
  known_data: knownData,

  // Chat history
  chat_history: chatHistory.slice(0, 10),
  chat_history_text: chatHistoryText,

  // Meta
  timestamp: trigger.timestamp,
  is_callback: trigger.is_callback,
  callback_data: trigger.callback_data
};
